using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogSnapshotTests{[Fact]public void KnowledgeCatalogSnapshot_orders_copies_and_projects(){var list=new List<AstronomyKnowledgeCatalogEntry>{KnowledgeCatalogFixture.Entry(AstronomyKnowledgeCatalogEntryKind.StatementKind,"b","b",2),KnowledgeCatalogFixture.Entry(AstronomyKnowledgeCatalogEntryKind.Domain,"a","a",1)};var s=new AstronomyKnowledgeCatalogSnapshot(list);list.Clear();Assert.Equal(["a","b"],s.Entries.Select(e=>e.Code));Assert.Single(s.Domains);Assert.Single(s.StatementKinds);Assert.Throws<NotSupportedException>(()=>((IList<AstronomyKnowledgeCatalogEntry>)s.Entries).Add(KnowledgeCatalogFixture.Entry()));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeCatalogSnapshot([KnowledgeCatalogFixture.Entry(),KnowledgeCatalogFixture.Entry()]));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeCatalogSnapshot([KnowledgeCatalogFixture.Entry(v:"a",c:"same"),KnowledgeCatalogFixture.Entry(v:"b",c:"same")]));var empty=new AstronomyKnowledgeCatalogSnapshot([]);Assert.Empty(empty.Entries);}}
